"""Original listening tasks. Kana is produced by the offline speech generator."""
import json
from pathlib import Path
rows=[]
def add(kind,title,jp,no,en,prompt,options,answer,evidence):
 n=len(rows)+1
 rows.append(dict(id=f'fl{n}',subject='Listening',kind=kind,title=title,prompt=prompt,options=options,answer=answer,explanation=evidence,transcript=jp,translationNo=no,translationEn=en,audioSrc=f'/audio/fl{n}.mp3',provenance='Sakura N4 original, AI-assisted',reviewStatus='internally-checked',audioOnlyChoices=kind in ['quick-response','utterance-expression']))
# Task-based comprehension: choose the action that follows from the exchange.
add('task-comprehension','At the bag shop','客：すみません。このかばんはいくらですか。店員：三千円です。客：青いのもありますか。店員：はい。でも、青いのは三千五百円です。客：では、この黒いのをください。','Kunden spør om prisen. Vesken koster 3000 yen, den blå 3500. Kunden velger den svarte.','The bag costs 3,000 yen; the blue one is 3,500. The customer chooses black.','客はどのかばんを買いますか。',['青いかばん','黒いかばん','赤いかばん','白いかばん'],1,'この黒いのをください explicitly selects black; the blue price is a distractor.')
add('task-comprehension','Clinic appointment','患者：明日の午後、予約できますか。受付：二時はいっぱいですが、三時半なら空いています。患者：では、三時半にお願いします。受付：初めてですから、十五分前に来てください。','Pasienten får time klokken 15.30 og må møte 15 minutter før fordi det er første besøk.','The appointment is at 3:30; a first-time patient must arrive 15 minutes early.','患者は何時に受付に行けばいいですか。',['二時','三時','三時十五分','三時半'],2,'Appointment 15:30 minus 15 minutes = 15:15 / 3:15. The requested time and arrival time differ.')
add('task-comprehension','Before the meeting','女：会議の前に資料をコピーしましょうか。男：コピーはもうしました。先に机を並べてください。飲み物は私が用意します。女：分かりました。','Kopiene er ferdige. Kvinnen skal først ordne bordene; mannen ordner drikke.','Copies are done. The woman should arrange tables first; the man handles drinks.','女の人はまず何をしますか。',['机を並べます。','資料をコピーします。','飲み物を買います。','会議を終わります。'],0,'先に机を並べてください is the first requested action. コピーはもうしました rules out copying.')
add('task-comprehension','A train change','客：さくら駅まで行きたいんですが。駅員：この電車はさくら駅には止まりません。次のみどり駅で降りて、普通電車に乗り換えてください。客：みどり駅ですね。ありがとうございます。','Dette toget stopper ikke ved Sakura. Kunden skal gå av på neste stasjon, Midori, og bytte til lokaltog.','The train does not stop at Sakura. Get off at the next station, Midori, and change to a local train.','客は次にどうしますか。',['この電車でさくら駅まで行きます。','今の駅で一時間待ちます。','みどり駅から歩きます。','みどり駅で普通電車に乗り換えます。'],3,'The staff explicitly directs a change to a local train at みどり駅, not walking or staying aboard.')
add('task-comprehension','Return a library book','学生：借りた本を返しに来たんですが、受付が閉まっています。係：返すだけなら、入り口の青い箱に入れてください。赤い箱は新聞用です。学生：分かりました。','Boken skal i den blå boksen ved inngangen. Den røde er for aviser.','Put the book in the blue box at the entrance; the red box is for newspapers.','学生は本をどこに入れますか。',['受付の机の上','入り口の青い箱','入り口の赤い箱','新聞の棚'],1,'入り口の青い箱 is specified for book returns; the red box is for newspapers.')
add('task-comprehension','Shopping for dinner','母：帰りに卵と牛乳を買ってきて。子：パンもいる？母：パンはまだあるから、いらないよ。あ、牛乳も冷蔵庫にあった。卵だけお願い。子：分かった。','Moren ber først om egg og melk, men oppdager at de har melk. Bare egg skal kjøpes.','Mother first asks for eggs and milk, then finds milk in the fridge. Only eggs are needed.','子供は何を買いますか。',['卵と牛乳','パンと卵','卵だけ','牛乳だけ'],2,'The final correction 卵だけお願い overrides the earlier shopping list.')
add('task-comprehension','Borrowing an umbrella','男：雨が降ってきたね。傘を忘れたよ。女：私のを貸そうか。私はここでバスに乗るから。男：ありがとう。明日返すね。女：うん。バス停まで一緒に使おう。','Kvinnen låner bort paraplyen, men de skal først dele den fram til busstoppet.','She lends him her umbrella; first they will share it as far as the bus stop.','二人はまずどうしますか。',['一緒にバス停まで行きます。','駅で傘を買います。','明日傘を返します。','それぞれ家へ帰ります。'],0,'バス停まで一緒に使おう establishes the immediate shared walk. Returning tomorrow is later.')
add('task-comprehension','A hotel room problem','客：部屋の電気がつきません。係：申し訳ありません。すぐ見に行きます。客：今から食事に出ます。係：では、お戻りになるまでに直します。鍵を受付に預けてください。','Gjesten skal ut og spise. Hotellet skal reparere lyset; nøkkelen skal leveres i resepsjonen.','The guest is going out to eat. Staff will repair the light; the key should be left at reception.','客は出かける前に何をしますか。',['電気を自分で直します。','部屋を変えます。','食事を部屋で待ちます。','鍵を受付に預けます。'],3,'鍵を受付に預けてください is the explicit action before leaving.')
# Point comprehension: listen for a reason, preference, change or key detail.
add('point-comprehension','A late bus','男：遅くなってごめん。女：寝坊したの？男：ううん。早く出たんだけど、事故でバスが動かなかったんだ。途中から歩いてきたよ。','Mannen dro tidlig, men bussen stod på grunn av en ulykke. Han gikk resten av veien.','He left early but an accident stopped the bus. He walked the rest of the way.','男の人が遅れた理由は何ですか。',['道を間違えたから','寝坊したから','バスが事故で動かなかったから','約束を忘れたから'],2,'事故でバスが動かなかった is the stated cause; he denies oversleeping.')
add('point-comprehension','Choosing a restaurant','女：駅前のレストランに行かない？安くて近いよ。男：でも、あそこはいつも込んでいるね。今日は静かな所でゆっくり話したいな。女：じゃあ、公園の近くの店にしよう。','Han ønsker et stille sted der de kan snakke rolig, ikke den travle restauranten ved stasjonen.','He wants a quiet place for a relaxed conversation rather than the crowded station restaurant.','男の人はどんな店に行きたいですか。',['静かな店','一番安い店','駅に一番近い店','人が多い店'],0,'静かな所でゆっくり話したい states his priority; cheapness and proximity were her suggestions.')
add('point-comprehension','A class announcement','先生：来週の授業は、教室ではなく、美術館で行います。いつもは九時に始まりますが、来週は九時半に美術館の入り口に集まってください。切符はこちらで用意します。','Neste uke møtes klassen ved museets inngang klokken 9.30. Læreren ordner billetter.','Next week the class meets at the museum entrance at 9:30. The teacher provides tickets.','来週、学生はどこに集まりますか。',['いつもの教室','美術館の入り口','学校の入り口','駅の改札'],1,'美術館の入り口に集まってください directly identifies the meeting place.')
add('point-comprehension','A birthday present','男：お母さんの誕生日に何をあげるの？女：去年は花をあげたけど、今年は一緒に食事に行くつもり。忙しくて最近あまり話していないから。男：それはいいね。','I år vil hun spise med moren fordi de ikke har fått snakket mye sammen i det siste.','This year she plans a meal with her mother because they have not had much time to talk.','女の人は今年、何をするつもりですか。',['花を買います。','手紙だけ送ります。','母と食事に行きます。','母に時計をあげます。'],2,'今年は一緒に食事に行くつもり is the plan; flowers were last year’s gift.')
add('point-comprehension','Apartment choice','女：新しい部屋はどう？男：駅から少し遠いけど、とても気に入っているよ。女：広いの？男：そんなに広くない。でも、窓から川が見えて、夜も静かなんだ。','Rommet er ikke stort og ligger litt langt fra stasjonen, men han liker utsikten mot elven og roen om natten.','The room is not large and is a little far from the station, but he likes the river view and quiet nights.','男の人が部屋を気に入っているのはなぜですか。',['家賃が無料だから','駅に近いから','とても広いから','景色がよくて静かだから'],3,'The positive details are the river view and quiet nights; size and station distance are not advantages.')
add('point-comprehension','Opening hours','放送：お客様にお知らせします。本日は店内の点検のため、いつもより一時間早く、午後七時に閉店いたします。明日は通常どおり、午前十時から営業いたします。','Butikken stenger i dag klokken 19, én time tidligere enn vanlig. I morgen åpner den normalt klokken 10.','Today the store closes at 7 p.m., one hour early. Tomorrow it opens as usual at 10 a.m.','この店は普段、何時に閉まりますか。',['午後六時','午後七時','午後八時','午前十時'],2,'Seven is one hour earlier than usual, so the usual closing time is eight p.m. / kl. 20.')
add('point-comprehension','Weekend plan','男：日曜日、山へ行く？女：天気予報では雨だって。男：じゃあ、映画はどう？女：見たい映画がないんだ。図書館の写真展に行こうよ。男：いいね。そこにしよう。','De velger en fotoutstilling på biblioteket i stedet for fjelltur i regn eller kino.','They choose the library photo exhibition instead of a rainy mountain trip or a film.','二人は日曜日、どこへ行きますか。',['図書館の写真展','映画館','山','写真を撮る店'],0,'図書館の写真展 is the final accepted proposal. 山 and 映画 are rejected alternatives.')
# Utterance expressions: situation and numbered responses are all on the recording.
add('utterance-expression','Requesting a pen','場面：試験中です。ペンを忘れました。隣の人にペンを借りたいです。何と言いますか。','Prøven er i gang. Du har glemt penn og ønsker å låne en av personen ved siden av.','During a test you forgot a pen and want to borrow one from the person next to you.','何と言いますか。',['ペンを貸していただけませんか。','ペンを返してもいいですか。','ペンを捨ててください。'],0,'貸していただけませんか is a polite request to borrow. Returning and throwing away do not fit.')
add('utterance-expression','Thanking a host','場面：友達の家で夕食を食べました。食べ終わりました。何と言いますか。','Du har nettopp spist ferdig middag hjemme hos en venn.','You have just finished dinner at a friend’s home.','何と言いますか。',['いただきます。','ごちそうさまでした。','いってきます。'],1,'ごちそうさまでした is said after a meal; いただきます is before eating.')
add('utterance-expression','Declining an invitation','場面：友達に明日の映画に誘われました。でも、明日は仕事があります。丁寧に断ります。何と言いますか。','Du blir invitert på kino i morgen, men må jobbe og vil takke høflig nei.','You are invited to a film tomorrow but have work and want to decline politely.','何と言いますか。',['もちろん、明日行きます。','映画を見てください。','残念ですが、明日は仕事があるんです。'],2,'残念ですが plus a reason declines politely. The first option accepts, contradicting the situation.')
add('utterance-expression','Apologizing for lateness','場面：約束の時間に10分遅れました。友達が待っています。何と言いますか。','Du kommer ti minutter for sent til en avtale og vennen din venter.','You arrive ten minutes late and your friend is waiting.','何と言いますか。',['待たせてごめんなさい。','待ってくれてすみませんでしたか。','お先に失礼します。'],0,'待たせてごめんなさい apologizes for making someone wait. The second is an unnatural question; the third means leaving first.')
add('utterance-expression','Offering help','場面：駅の階段で、大きな荷物を持った人が困っています。手伝いたいです。何と言いますか。','En person sliter med tung bagasje i stasjonen. Du vil tilby hjelp.','Someone is struggling with luggage on station stairs and you want to help.','何と言いますか。',['荷物を持ってください。','荷物を持ちましょうか。','荷物を持ってもらいました。'],1,'持ちましょうか offers to carry it. 持ってください asks the other person to carry it.')
# Quick responses: all answer alternatives are spoken, only numbers shown in exam.
add('quick-response','A greeting','同僚：お先に失礼します。','En kollega sier at han/hun går før deg.','A colleague says they are leaving before you.','最もよい返事を選んでください。',['いってきます。','いただきます。','お疲れさまでした。'],2,'お疲れさまでした is the conventional response to a colleague leaving work.')
add('quick-response','An invitation','友達：一緒にコーヒーでも飲みませんか。','En venn inviterer deg på kaffe.','A friend invites you for coffee.','最もよい返事を選んでください。',['いいですね。行きましょう。','どういたしまして。','お大事に。'],0,'いいですね。行きましょう accepts the invitation; the other responses concern thanks and illness.')
add('quick-response','Permission','学生：この席に座ってもいいですか。','En student spør om det er lov å sitte her.','A student asks whether they may sit here.','最もよい返事を選んでください。',['ごちそうさまでした。','ええ、どうぞ。','それは座りました。'],1,'ええ、どうぞ grants permission / ja, vær så god.')
add('quick-response','A request','先生：明日までにこの本を読んでおいてください。','Læreren ber deg lese boken innen i morgen.','The teacher asks you to read this book by tomorrow.','最もよい返事を選んでください。',['もう帰りました。','本ではありません。','はい、分かりました。'],2,'はい、分かりました acknowledges the instruction. The alternatives do not respond appropriately.')
add('quick-response','A lost item','駅員：どんなかばんをなくしたんですか。','Stasjonsansatte spør hva slags veske du mistet.','Station staff asks what kind of bag you lost.','最もよい返事を選んでください。',['黒くて小さいかばんです。','駅まで十分です。','三人で来ました。'],0,'A color/size description answers どんなかばん. The other choices give travel time or party size.')
add('quick-response','A compliment','友達：そのシャツ、よく似合っていますね。','En venn sier at skjorten kler deg.','A friend says the shirt suits you.','最もよい返事を選んでください。',['お大事に。','ありがとうございます。','お帰りなさい。'],1,'ありがとうございます appropriately acknowledges a compliment / takk.')
add('quick-response','An illness','友達：昨日から熱があるんです。','En venn forteller at han/hun har hatt feber siden i går.','A friend says they have had a fever since yesterday.','最もよい返事を選んでください。',['おめでとうございます。','ごちそうさまでした。','それはいけませんね。お大事に。'],2,'それはいけませんね。お大事に expresses concern and wishes recovery; congratulations is inappropriate.')
add('quick-response','Finding the way','客：すみません。郵便局はどこですか。','En person spør hvor postkontoret er.','A person asks where the post office is.','最もよい返事を選んでください。',['この道をまっすぐ行くと、右にあります。','切手を二枚ください。','昨日、手紙を書きました。'],0,'The first response gives directions. Asking for stamps and describing a letter do not locate the office.')
kana=json.loads((Path(__file__).parent/'listening_kana.json').read_text())
for r in rows:
 r['kana']=kana[r['id']]
 # Record exactly what is synthesized, including spoken question and response-only choices.
 r['spokenText']=r['transcript']+'。'+r['prompt']
 if r['audioOnlyChoices']:
  r['spokenText']+='。'+'。'.join(f'{i+1}番。{o}' for i,o in enumerate(r['options']))
Path('src/mock-listening.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
print('Listening questions:',len(rows))
